def get_dftd4_default_params(xc: str = "pbe") -> Dict[str, float]:
    """Return DFT-D4 damping parameters {s6, s8, s9, a1, a2, alp} for the functional ``xc``.

    Names are case-insensitive; hyphens are ignored (``"r2scan"``, ``"pbe0"``, ``"b3-lyp"`` ...).
    """
    key = xc.lower().replace("-", "")
    for k, v in _DFTD4_PARAMS.items():
        if k.replace("-", "") == key:
            return dict(v)
    raise ValueError(f"Unknown xc functional for DFT-D4: {xc!r}. Available: {sorted(_DFTD4_PARAMS)}")
